-- ========================================================================
-- ARABI SPEED: supplied PreSimulation / normalized XZ AssemblyLinearVelocity.
-- The supplied Arabi file updates a spoof vector but contains NO velocity read
-- hook. No Haze LinearVelocity constraint, hook, loader or unrelated Arabi code.
-- ========================================================================
local function isRagdollState(hum)
    if not hum then return true end
    local state = hum:GetState()
    return hum.PlatformStand or state == Enum.HumanoidStateType.Physics
        or state == Enum.HumanoidStateType.Ragdoll or state == Enum.HumanoidStateType.FallingDown
end

local Speed = {alive = true, connections = {}, lastMoveDir = Vector3.zero, spoofedVelocity = Vector3.zero}
function Speed.pathActive() return State.autoLeftEnabled or State.autoRightEnabled end

-- Horizon Auto Switch Carry Speed port. It only switches speed while a steal /
-- carry handoff is active; enabling the button does not force Carry forever.
local AutoCarry = {
    nearAt = 0, nearValue = false,
}

local function isCarryName(name)
    local value = tostring(name or ""):lower()
    return value:find("brainrot") or value:find("animal") or value:find("carry")
        or value:find("grab") or value:find("steal") or value:find("hold")
end

local function isIgnoredCarryTool(name)
    local value = tostring(name or ""):lower()
    return value:find("bat") or value:find("slap") or value:find("medusa")
        or value:find("head") or value:find("stone")
end

local function isCarryingBrainrot(char)
    if not char then return false end
    for _, name in ipairs({"Carrying", "IsCarrying", "Grabbed", "Holding", "StealHold", "HasGrab"}) do
        local value = char:FindFirstChild(name, true)
        if value then
            if value:IsA("BoolValue") and value.Value then return true end
            if value:IsA("ObjectValue") and value.Value then return true end
            if value:IsA("StringValue") and value.Value ~= "" then return true end
        end
    end
    for _, child in ipairs(char:GetChildren()) do
        if child:IsA("Model") and child:FindFirstChildWhichIsA("BasePart", true) then
            if child:FindFirstChildOfClass("Humanoid") and child:FindFirstChild("HumanoidRootPart") then return true end
            if isCarryName(child.Name) then return true end
        elseif child:IsA("Tool") and not isIgnoredCarryTool(child.Name) then
            return true
        end
    end
    return false
end

local function isNearBrainrot(char)
    local now = tick()
    if now - AutoCarry.nearAt < 0.15 then return AutoCarry.nearValue end
    AutoCarry.nearAt, AutoCarry.nearValue = now, false
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not root then return false end
    for _, prompt in ipairs(workspace:GetDescendants()) do
        if prompt:IsA("ProximityPrompt") then
            local holder = prompt.Parent
            local part = holder and holder:IsA("BasePart") and holder
                or holder and holder:FindFirstAncestorWhichIsA("BasePart")
            if part and (part.Position - root.Position).Magnitude <= 11 then
                AutoCarry.nearValue = true
                return true
            end
        end
    end
    return false
end

local function setAutoCarryBaseMode(on)
    State.speedMode = on == true
end

local function enableAutoCarrySpeed()
    if not State.autoCarryFromSteal then
        State.autoCarryReturnMode = (State.laggerToggled and State.laggerPhase == 2 and "Lagger Carry")
            or (State.laggerToggled and "Lagger")
            or (State.speedMode and "Carry")
            or "Normal"
    end
    State.autoCarryFromSteal = true
    State.autoCarryGraceUntil = tick() + 0.75
    if State.autoCarryReturnMode == "Lagger" or State.autoCarryReturnMode == "Lagger Carry" then
        State.laggerToggled = true
        State.laggerPhase = 2
        State.speedMode = false
    else
        setAutoCarryBaseMode(true)
    end
    if Speed.refreshVisuals then Speed.refreshVisuals() end
end

local function disableAutoCarrySpeed()
    if not State.autoCarryFromSteal and not State.autoCarryWaitingForPickup then return end
    local returnMode = State.autoCarryReturnMode
    State.autoCarryFromSteal = false
    State.autoCarryWaitingForPickup = false
    State.autoCarryReturnMode = nil
    if returnMode == "Lagger Carry" then
        State.laggerToggled, State.laggerPhase, State.speedMode = true, 2, false
    elseif returnMode == "Lagger" then
        State.laggerToggled, State.laggerPhase, State.speedMode = true, 1, false
    elseif returnMode == "Carry" then
        State.laggerToggled, State.laggerPhase, State.speedMode = false, 0, true
    else
        State.laggerToggled, State.laggerPhase, State.speedMode = false, 0, false
    end
    State.autoCarryLastSpeed = 0
    if Speed.refreshVisuals then Speed.refreshVisuals() end
end

function Speed.updateAutoCarry(char, hum)
    if not State.autoCarrySpeedEnabled then
        if State.autoCarryFromSteal then disableAutoCarrySpeed() end
        return
    end
    local gotHit = isRagdollState(hum)
    local stealingAttr = LP:GetAttribute("Stealing") == true
    local nearBrainrot = isNearBrainrot(char)
    local carryingBrainrot = isCarryingBrainrot(char) or nearBrainrot or State.isStealing
    if nearBrainrot and not State.autoCarryFromSteal then enableAutoCarrySpeed() end
    if stealingAttr and not State.stealAttrWasActive then
        State.stealAttrWasActive = true
        enableAutoCarrySpeed()
    elseif not stealingAttr then
        State.stealAttrWasActive = false
    end
    if State.autoCarryWaitingForPickup then
        if gotHit or tick() > (State.autoCarryPickupWatchUntil or 0) then
            State.autoCarryWaitingForPickup = false
        elseif carryingBrainrot then
            enableAutoCarrySpeed()
        end
    end
    if carryingBrainrot and not State.autoCarryFromSteal then enableAutoCarrySpeed() end
    if State.autoCarryFromSteal and (gotHit
        or (tick() > State.autoCarryGraceUntil and not carryingBrainrot and not stealingAttr)) then
        disableAutoCarrySpeed()
    end
end

local function getActiveMoveSpeed()
    if Speed.pathActive() then return State.NS end
    if State.autoCarryFromSteal then
        if State.autoCarryReturnMode == "Lagger" or State.autoCarryReturnMode == "Lagger Carry" then
            return State.LAGGER_CARRY_SPEED
        end
        return State.CS
    end
    local carry = State.speedMode or (State.laggerToggled and State.laggerPhase == 2)
    if State.laggerToggled and carry then return State.LAGGER_CARRY_SPEED end
    if State.laggerToggled then return State.LAGGER_SPEED end
    if carry then return State.CS end
    return State.NS
end
local function getAutoPathSpeed()
    return State.NS
end
do
    function Speed.readVelocity(root) return root.AssemblyLinearVelocity end
    function Speed.writeVelocity(root, value) root.AssemblyLinearVelocity = value end
    function Speed.suspend() Speed.lastMoveDir = Vector3.zero end
    function Speed.blocked()
        return State.autoBatEnabled or State.autoLeftEnabled or State.autoRightEnabled
            or State.tpBatEnabled or State.dropActive or State.unwalkEnabled or State.ragdollTpBusy
    end
    function Speed.syncSpoofFromReal(root)
        local velocity = root.AssemblyLinearVelocity
        local flat = Vector3.new(velocity.X, 0, velocity.Z)
        if flat.Magnitude > 1 then
            local unit = flat.Unit
            Speed.spoofedVelocity = Vector3.new(unit.X * 16, velocity.Y, unit.Z * 16)
        else
            Speed.spoofedVelocity = Vector3.new(0, velocity.Y, 0)
        end
    end
    function Speed.applyDrive(root, flat, speed)
        local realY = root.AssemblyLinearVelocity.Y
        root.AssemblyLinearVelocity = Vector3.new(flat.X * speed, realY, flat.Z * speed)
    end
    function Speed.step()
        if not Speed.alive then return end
        local char, hum, root = getCharData()
        if not char or not hum or not root or hum.Health <= 0 then return end
        Speed.updateAutoCarry(char, hum)
        if isRagdollState(hum) then
            Speed.lastMoveDir = Vector3.zero
            Speed.syncSpoofFromReal(root)
            return
        end
        if Speed.blocked() then
            if State.autoBatEnabled or State.tpBatEnabled then Speed.lastMoveDir = Vector3.zero end
            Speed.syncSpoofFromReal(root)
        else
            local direction = hum.MoveDirection
            if direction.Magnitude > 0 then
                Speed.lastMoveDir = direction
            elseif State.antiRagdollEnabled and Speed.lastMoveDir.Magnitude > 0 then
                for key in pairs(MOVE_KEYS) do
                    if UserInputService:IsKeyDown(key) then direction = Speed.lastMoveDir; break end
                end
            end
            if direction and direction.Magnitude > 0 then
                local flat = Vector3.new(direction.X, 0, direction.Z)
                if flat.Magnitude > 0 then flat = flat.Unit end
                pcall(function() root:SetNetworkOwner(LP) end)
                local activeSpeed = getActiveMoveSpeed()
                if State.autoCarryFromSteal then
                    if State.autoCarryLastSpeed <= 0 then
                        State.autoCarryLastSpeed = activeSpeed
                    else
                        State.autoCarryLastSpeed = State.autoCarryLastSpeed * 0.85 + activeSpeed * 0.15
                    end
                    activeSpeed = State.autoCarryLastSpeed
                else
                    State.autoCarryLastSpeed = 0
                end
                Speed.applyDrive(root, flat, activeSpeed)
            else
                -- Arabi preserves real momentum at idle; it only updates this cache.
                if State.autoCarryFromSteal then State.autoCarryLastSpeed = 0 end
                Speed.syncSpoofFromReal(root)
            end
        end
        if speedLabel and not State.isStealing then
            local velocity = root.AssemblyLinearVelocity
            speedLabel.Text = string.format("%.1f", Vector3.new(velocity.X, 0, velocity.Z).Magnitude)
        end
    end
    function Speed.destroy()
        if not Speed.alive then return end
        Speed.alive = false
        for _, connection in ipairs(Speed.connections) do connection:Disconnect() end
        table.clear(Speed.connections)
        Speed.lastMoveDir, Speed.spoofedVelocity = Vector3.zero, Vector3.zero
    end
    table.insert(Speed.connections, RunService.PreSimulation:Connect(Speed.step))
    table.insert(Speed.connections, LP.CharacterRemoving:Connect(function()
        Speed.lastMoveDir, Speed.spoofedVelocity = Vector3.zero, Vector3.zero
    end))
    UI.addCleanup(Speed.destroy)
end
local function applyPathMovement(hum, root, moveDir, speed)
    if not hum or not root then return end
    Speed.applyDrive(root, moveDir, speed)
end

-- ========================================================================
-- TP BAT: CZ BAT TP operating logic only; no donor GUI / key listener / config.
-- T (or the existing rebound key), hub toggle and mobile button share this state.
-- ========================================================================
local TpBat = {
    alive = true, generation = 0, hittingCooldown = false, connections = {},
    autoBatWasEnabled = false, grabWasRunning = false, grabWasSemi = false,
    antiDieWasEnabled = false, antiDieForced = false,
}
do
    -- Horizon TP BAT core: PhysicsRepRootPart handoff, closest-player tracking,
    -- camera follow and the Bat activation cooldown. The M10RU UI is kept out of
    -- the engine so PC, gamepad and mobile controls share exactly one state.
    local function disconnect(connection)
        if connection then pcall(function() connection:Disconnect() end) end
    end
    local function getHidden(root)
        local getter = gethiddenproperty or get_hidden_property
        if getter then
            local ok, value = pcall(getter, root, "PhysicsRepRootPart")
            if ok then return true, value end
        end
        local ok, value = pcall(function() return root.PhysicsRepRootPart end)
        return ok, value
    end
    local function setHidden(root, value)
        local setter = sethiddenproperty or set_hidden_property
        if setter then
            local ok = pcall(setter, root, "PhysicsRepRootPart", value)
            if ok then return true end
        end
        return pcall(function() root.PhysicsRepRootPart = value end)
    end
    local function releaseRoot()
        if TpBat.owner then
            if TpBat.hadOriginal then
                setHidden(TpBat.owner, TpBat.original)
            else
                setHidden(TpBat.owner, TpBat.owner)
            end
        end
        TpBat.owner, TpBat.original, TpBat.hadOriginal = nil, nil, nil
    end
    local function getBatTP()
        local char = LP.Character
        if not char then return nil end
        local bat = char:FindFirstChild("Bat")
        if bat then return bat end
        local backpack = LP:FindFirstChild("Backpack")
        bat = backpack and backpack:FindFirstChild("Bat")
        if bat then
            local humanoid = char:FindFirstChildOfClass("Humanoid")
            if humanoid then pcall(function() humanoid:EquipTool(bat) end) end
            return bat
        end
        return nil
    end
    local function tryHitBatTP()
        if TpBat.hittingCooldown then return end
        TpBat.hittingCooldown = true
        local generation = TpBat.generation
        pcall(function()
            local bat = getBatTP()
            if bat then
                bat:Activate()
                local remote = bat:FindFirstChildWhichIsA("RemoteEvent")
                if remote then remote:FireServer() end
            end
        end)
        task.delay(0.08, function()
            if TpBat.alive and TpBat.generation == generation then TpBat.hittingCooldown = false end
        end)
    end
    local function suspendCompetingFeatures()
        TpBat.autoBatWasEnabled = State.autoBatEnabled == true
        if TpBat.autoBatWasEnabled and Combat.stopGood then pcall(Combat.stopGood) end
        if State.autoLeftEnabled then
            State.autoLeftEnabled = false
            if Conns.autoLeft then disconnect(Conns.autoLeft); Conns.autoLeft = nil end
        end
        if State.autoRightEnabled then
            State.autoRightEnabled = false
            if Conns.autoRight then disconnect(Conns.autoRight); Conns.autoRight = nil end
        end
        TpBat.grabWasRunning = State.SemiNormalOpen or State.SemiEnabled
        TpBat.grabWasSemi = State.SemiEnabled == true
        if TpBat.grabWasRunning then Grab.stopAll() end
        TpBat.antiDieWasEnabled = State.antiDieEnabled == true
        if not TpBat.antiDieWasEnabled and AntiDie and AntiDie.setEnabled then
            TpBat.antiDieForced = true
            State.antiDieEnabled = true
            pcall(function() AntiDie.setEnabled(true) end)
        end
    end
    local function restoreCompetingFeatures()
        if TpBat.antiDieForced and AntiDie and AntiDie.setEnabled then
            State.antiDieEnabled = false
            pcall(function() AntiDie.setEnabled(false) end)
        end
        TpBat.antiDieForced = false
        if TpBat.autoBatWasEnabled and Combat.startGood then pcall(Combat.startGood) end
        TpBat.autoBatWasEnabled = false
        if TpBat.grabWasRunning then
            if TpBat.grabWasSemi then Grab.startSemi() else Grab.startNormal() end
        end
        TpBat.grabWasRunning, TpBat.grabWasSemi = false, false
    end

    function TpBat.refresh()
        if TpBat.uiSet then TpBat.uiSet(State.tpBatEnabled) end
        if TpBat.mobileSet then TpBat.mobileSet(State.tpBatEnabled) end
    end

    function TpBat.step()
        if not TpBat.alive or not State.tpBatEnabled or State.ragdollTpBusy then return end
        local char, humanoid, root = getCharData()
        if not char or not humanoid or humanoid.Health <= 0 or not root then releaseRoot(); return end
        local nearest, distance = nil, math.huge
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LP and player.Character then
                local target = player.Character:FindFirstChild("HumanoidRootPart")
                local targetHumanoid = player.Character:FindFirstChildOfClass("Humanoid")
                if target and (not targetHumanoid or targetHumanoid.Health > 0) then
                    local d = (root.Position - target.Position).Magnitude
                    if d < distance then nearest, distance = target, d end
                end
            end
        end
        if not nearest then releaseRoot(); return end
        Speed.suspend()
        if TpBat.owner ~= root then
            releaseRoot()
            TpBat.owner = root
            TpBat.hadOriginal, TpBat.original = getHidden(root)
        end
        setHidden(root, nearest)
        local targetPosition = nearest.Position + Vector3.new(0, 0.9, 0)
        if (root.Position - targetPosition).Magnitude > 8 then root.CFrame = CFrame.new(targetPosition) end
        local camera = workspace.CurrentCamera
        if camera then camera.CFrame = CFrame.new(camera.CFrame.Position, nearest.Position) end
        tryHitBatTP()
    end

    function TpBat.setEnabled(on)
        if not TpBat.alive then return false end
        on = on == true
        if State.tpBatEnabled == on then TpBat.refresh(); return on end
        TpBat.generation += 1
        State.tpBatEnabled = on
        TpBat.hittingCooldown = false
        if TpBat.heartbeat then TpBat.heartbeat:Disconnect(); TpBat.heartbeat = nil end
        releaseRoot()
        if on then
            suspendCompetingFeatures()
            Speed.suspend()
            TpBat.heartbeat = RunService.Heartbeat:Connect(function()
                local ok, err = pcall(TpBat.step)
                if not ok and not TpBat.reportedError then
                    TpBat.reportedError = true
                    warn("[M10RU Duels TP BAT] " .. tostring(err))
                end
            end)
        else
            restoreCompetingFeatures()
        end
        TpBat.refresh()
        return on
    end

    function TpBat.toggle() return TpBat.setEnabled(not State.tpBatEnabled) end

    function TpBat.destroy()
        if not TpBat.alive then return end
        TpBat.setEnabled(false)
        TpBat.alive = false
        for _, connection in ipairs(TpBat.connections) do disconnect(connection) end
        table.clear(TpBat.connections)
    end

    table.insert(TpBat.connections, LP.CharacterRemoving:Connect(function()
        TpBat.generation += 1
        TpBat.hittingCooldown = false
        releaseRoot()
    end))
    UI.addCleanup(TpBat.destroy)
end

-- Optimized Player Collision (Throttled & safe)
task.spawn(function()
    while true do
        task.wait(0.5)
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP and p.Character then
                for _, part in ipairs(p.Character:GetChildren()) do
                    if part:IsA("BasePart") and part.CanCollide then
                        part.CanCollide = false
                    end
                end
            end
        end
    end
end)

-- ========================================================================
-- PLOT DETECTION
-- ========================================================================
local function isMyPlotByName(plotName)
    local plots = workspace:FindFirstChild("Plots")
    if not plots then return false end
    local plot = plots:FindFirstChild(plotName)
    if not plot then return false end
    local sign = plot:FindFirstChild("PlotSign")
    if sign then
        local yb = sign:FindFirstChild("YourBase")
        if yb and yb:IsA("BillboardGui") then
            return yb.Enabled == true
        end
    end
    return false
end

local function getMyPlot()
    for plotNum, plotPos in pairs({[3] = State.PLOT3_POS, [7] = State.PLOT7_POS}) do
        for _, obj in ipairs(workspace:GetDescendants()) do
            if obj:IsA("BasePart") and obj.Name == "PlotSign" then
                if (obj.Position - plotPos).Magnitude < 5 then
                    for _, child in ipairs(obj:GetDescendants()) do
                        if child:IsA("SurfaceGui") then
                            for _, label in ipairs(child:GetDescendants()) do
                                if label:IsA("TextLabel") and label.Text ~= "" then
                                    if string.find(label.Text, LP.Name) or string.find(label.Text, LP.DisplayName) then
                                        return plotNum
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    return nil
end

local function getMyPlotPosition()
    local plots = workspace:FindFirstChild("Plots")
    if not plots then return nil end
    for _, plot in ipairs(plots:GetChildren()) do
        if isMyPlotByName(plot.Name) then
            local sign = plot:FindFirstChild("PlotSign")
            if sign then return sign.Position + Vector3.new(0, 5, 0) end
            local ok, cf = pcall(function() return plot:GetModelCFrame() end)
            if ok and cf then return cf.Position + Vector3.new(0, 5, 0) end
        end
    end
    return nil
end

-- ========================================================================
-- AUTO GRAB: independent engines, shared skins, single active owner.
-- Normal V1/V2 keep their supplied ranges/timing. SEMI uses the second file.
-- Generation checks cancel old holds BEFORE another engine is enabled.
-- ========================================================================
do
    local function disconnect(connection)
        if connection then pcall(function() connection:Disconnect() end) end
    end

    function Grab.currentEngine()
        if State.SemiEnabled then return "SEMI" end
        if State.SemiNormalOpen then return State.SemiMode end
        return nil
    end

    function Grab.uiEngine()
        return Grab.currentEngine() or Grab.uiTarget or State.SemiMode
    end

    function Grab.getStyle(engine)
        return State.AutoGrabStyle[engine or Grab.uiEngine()] or 1
    end

    function Grab.getScale(engine)
        engine = engine or Grab.uiEngine()
        if engine == "V1" then return State.v1Scale end
        if engine == "V2" then return State.v2Scale end
        return State.semiScale
    end

    function Grab.applyScale()
        local scale = Grab.getScale()
        for _, view in pairs(Grab.views) do
            UI.animate(view.scale, {Scale = scale}, 0.28)
        end
    end

    function Grab.updateBars()
        local engine = Grab.currentEngine() or "V1"
        local style = Grab.getStyle(engine)
        local old = Grab.visibleStyle and Grab.views[Grab.visibleStyle]
        local incoming = style and Grab.views[style]
        if style ~= Grab.visibleStyle and incoming then
            if old and old ~= incoming then
                UI.cancel(incoming.frame, "Position")
                incoming.frame.Position = old.frame.Position
                UI.cancel(incoming.frame, "Size")
                incoming.frame.Size = old.frame.Size
                UI.animate(incoming.frame, {Position = UI.goal(old.frame, "Position")}, 0.24)
                UI.animate(old.frame, {Size = incoming.baseSize}, 0.24)
            end
            UI.animate(incoming.frame, {Size = incoming.baseSize}, 0.24)
        end
        if Grab.visualEngine ~= engine then
            -- Retain the visible value during a handover; the render filter eases
            -- toward the new engine. Reset only while the surface is not visible.
            if not UI.ready or (Grab.visualEngine == nil and incoming and not incoming.frame.Visible) then
                Grab.displayed = 0
            end
            Grab.visualEngine = engine
        end
        Grab.visibleStyle = style
        for number, view in pairs(Grab.views) do
            UI.show(view.frame, style == number)
        end
        Grab.applyScale()
    end

    function Grab.refresh()
        Grab.updateBars()
        if refreshSemiUI then refreshSemiUI() end
    end

    function Grab.setStyle(style, engine)
        if not Grab.alive or (style ~= 1 and style ~= 2) then return end
        engine = engine or Grab.uiEngine()
        if engine ~= "V1" and engine ~= "V2" and engine ~= "SEMI" then return end
        -- Appearance only: never stop/restart a hold or change engine settings.
        State.AutoGrabStyle[engine] = style
        Grab.refresh()
    end

    function Grab.changeScale(delta, engine)
        if not Grab.alive or type(delta) ~= "number" or delta ~= delta then return end
        engine = engine or Grab.uiEngine()
        local key = engine == "V1" and "v1Scale" or engine == "V2" and "v2Scale" or "semiScale"
        State[key] = math.clamp(math.floor((State[key] + delta) * 10 + 0.5) / 10, 0.5, 2)
        Grab.refresh()
    end

    local function syncIsStealing()
        local instant = Grab.instant and Grab.instant.session
        State.isStealing = State.isStealingV1 or State.isStealingV2
            or (instant ~= nil and instant.state.active == true)
    end

    local function valid(engine, epoch, character)
        return Grab.alive and Grab.epoch == epoch and Grab.currentEngine() == engine
            and (character == nil or LP.Character == character)
    end

    local function collectCallbacks(cache, prompt)
        if cache[prompt] then return cache[prompt] end
        local data = {hold = {}, trigger = {}, ready = true}
        if getconnections then
            for _, pair in ipairs({{prompt.PromptButtonHoldBegan, data.hold}, {prompt.Triggered, data.trigger}}) do
                local ok, connections = pcall(getconnections, pair[1])
                if ok and type(connections) == "table" then
                    for _, connection in ipairs(connections) do
                        if type(connection.Function) == "function" then
                            table.insert(pair[2], connection.Function)
                        end
                    end
                end
            end
        end
        cache[prompt] = data
        return data
    end

    local function dispatch(callbacks, stillValid)
        for _, callback in ipairs(callbacks) do
            task.spawn(function()
                if stillValid() then pcall(callback) end
            end)
        end
    end

    -- Target selection copied from the supplied hub.
    local function findNearestPromptV1()
        local char = LP.Character
        if not char then return nil, nil end
        local root = char:FindFirstChild("HumanoidRootPart")
        if not root then return nil, nil end
        local plots = workspace:FindFirstChild("Plots")
        if not plots then return nil, nil end

        local nearestPrompt, nearestDist, nearestName = nil, math.huge, nil
        for _, plot in ipairs(plots:GetChildren()) do
            if isMyPlotByName(plot.Name) then continue end
            local pods = plot:FindFirstChild("AnimalPodiums")
            if not pods then continue end
            for _, pod in ipairs(pods:GetChildren()) do
                pcall(function()
                    local base = pod:FindFirstChild("Base")
                    local spawn = base and base:FindFirstChild("Spawn")
                    if spawn then
                        local dist = (spawn.Position - root.Position).Magnitude
                        if dist < nearestDist and dist <= State.StealV1.StealRadius then
                            local att = spawn:FindFirstChild("PromptAttachment")
                            if att then
                                for _, child in ipairs(att:GetChildren()) do
                                    if child:IsA("ProximityPrompt") and child.ActionText and child.ActionText:find("Steal") then
                                        nearestPrompt = child
                                        nearestDist = dist
                                        nearestName = pod.Name
                                        break
                                    end
                                end
                            end
                        end
                    end
                end)
            end
        end
        return nearestPrompt, nearestName
    end
    local function findNearestPromptV2()
        local char = LP.Character
        local root = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso"))
        local plots = workspace:FindFirstChild("Plots")
        if not root or not plots then return nil end

        local nearest, distance = nil, math.huge
        for _, plot in ipairs(plots:GetChildren()) do
            if plot:IsA("Model") and not isMyPlotByName(plot.Name) then
                local podiums = plot:FindFirstChild("AnimalPodiums")
                if podiums then
                    for _, podium in ipairs(podiums:GetChildren()) do
                        local base = podium:FindFirstChild("Base")
                        local spawn = base and base:FindFirstChild("Spawn")
                        if spawn then
                            local d = (spawn.Position - root.Position).Magnitude
                            if d <= State.StealV2.StealRadius and d < distance then
                                local found
                                local attachment = spawn:FindFirstChild("PromptAttachment")
                                local candidates = attachment and attachment:GetChildren() or spawn:GetDescendants()
                                for _, pr in ipairs(candidates) do
                                    if pr:IsA("ProximityPrompt") and pr.ActionText and pr.ActionText:find("Steal") then
                                        found = pr
                                        break
                                    end
                                end
                                if found then nearest, distance = found, d end
                            end
                        end
                    end
                end
            end
        end
        return nearest
    end

    local function promptDistanceV2(prompt)
        local char = LP.Character
        local root = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso"))
        if not root then return math.huge end
        local part = prompt.Parent
        if part and part:IsA("Attachment") then part = part.Parent end
        if part and part:IsA("BasePart") then return (part.Position - root.Position).Magnitude end
        local ok, position = pcall(function() return prompt.Parent and prompt.Parent.WorldPosition end)
        return ok and position and (position - root.Position).Magnitude or math.huge
    end

    local function executeStealV1(prompt, podName)
        if State.isStealingV1 or not State.StealV1.AutoStealEnabled then return end
        local data = collectCallbacks(State.StealV1.Data, prompt)
        if not data.ready then return end
        local epoch, character = Grab.epoch, LP.Character
        if not character then return end
        local function current()
            return valid("V1", epoch, character) and State.StealV1.AutoStealEnabled
        end
        local function usable()
            return current() and prompt.Parent ~= nil and promptDistanceV2(prompt) <= State.StealV1.StealRadius
        end
        local function fire()
            if not usable() then return end
            dispatch(data.trigger, current)
            pcall(function()
                if not current() then return end
                local remote = ReplicatedStorage:FindFirstChild("StealAnimal")
                if remote and podName then remote:FireServer(podName) end
                if current() and prompt and prompt.Fire then prompt:Fire() end
            end)
        end

        data.ready = false
        State.isStealingV1 = true
        Grab.phaseV1 = "holding"
        Grab.progressV1 = 0
        syncIsStealing()
        task.spawn(function()
            local ok, err = pcall(function()
                if not current() then return end
                dispatch(data.hold, current)
                local startTime = tick()
                local duration = State.StealV1.StealDuration
                if State.autoGrabStopEnabled then
                    while usable() and tick() - startTime < State.autoGrabStopTime do
                        Grab.progressV1 = math.clamp((tick() - startTime) / duration, 0, 1)
                        task.wait()
                    end
                    if not usable() then return end
                    local stopProgress = math.clamp(State.autoGrabStopTime / duration, 0, 1)
                    Grab.progressV1 = stopProgress
                    Grab.phaseV1 = "waitingRange"
                    local phase2Timeout = math.max(2.99 - State.autoGrabStopTime - math.max(duration - State.autoGrabStopTime, 0), 0.05)
                    local phase2Start = tick()
                    while usable() and promptDistanceV2(prompt) > State.autoGrabSetDelayRadius do
                        if tick() - phase2Start >= phase2Timeout then return end
                        task.wait()
                    end
                    if not usable() then return end
                    Grab.phaseV1 = "finishing"
                    local fillStart = tick()
                    local fillDuration = math.max(duration - State.autoGrabStopTime, 0.05)
                    while usable() do
                        local progress = math.clamp((tick() - fillStart) / fillDuration, 0, 1)
                        Grab.progressV1 = stopProgress + progress * (1 - stopProgress)
                        if progress >= 1 then fire(); break end
                        task.wait()
                    end
                else
                    while usable() do
                        local elapsed = tick() - startTime
                        Grab.progressV1 = math.clamp(elapsed / duration, 0, 1)
                        if elapsed >= duration then fire(); break end
                        task.wait()
                    end
                end
            end)
            data.ready = true
            if Grab.epoch == epoch then
                Grab.progressV1 = 0
                Grab.phaseV1 = "idle"
                State.isStealingV1 = false
                syncIsStealing()
                if not ok then warn("[M10RU Duels AUTO GRAB V1] " .. tostring(err)) end
            end
        end)
    end

    local function executeStealV2(prompt)
        if State.isStealingV2 or not State.StealV2.AutoStealEnabled then return end
        local data = collectCallbacks(State.StealV2.Data, prompt)
        if not data.ready then return end
        local epoch, character, startTime = Grab.epoch, LP.Character, tick()
        if not character then return end
        local function current()
            return valid("V2", epoch, character) and State.StealV2.AutoStealEnabled and prompt.Parent ~= nil
        end
        data.ready = false
        State.isStealingV2 = true
        Grab.phaseV2 = "holding"
        State.stealStartTimeV2 = startTime
        syncIsStealing()
        task.spawn(function()
            local ok, err = pcall(function()
                if not current() then return end
                dispatch(data.hold, current)
                task.wait(State.StealV2.HalfHoldMin)
                if not current() then return end
                Grab.phaseV2 = "waitingRange"
                local inRange = promptDistanceV2(prompt) <= State.StealV2.HalfFireRange
                while current() do
                    if tick() - startTime > State.StealV2.HalfHoldMax then break end
                    if promptDistanceV2(prompt) <= State.StealV2.HalfFireRange then
                        if not inRange then task.wait(State.StealV2.HalfEntryDelay) end
                        if current() then dispatch(data.trigger, current) end
                        break
                    end
                    task.wait()
                end
                task.wait(0.05)
            end)
            data.ready = true
            if Grab.epoch == epoch then
                State.isStealingV2 = false
                Grab.phaseV2 = "idle"
                State.stealStartTimeV2 = nil
                syncIsStealing()
                if not ok then warn("[M10RU Duels AUTO GRAB V2] " .. tostring(err)) end
            end
        end)
    end

    -- SEMI: logic from "semi instant steal.txt", without its standalone UI,
    -- START/STOP button, status/name/RAD controls, prints, or automatic startup.
    -- Each activation has its own caches/connections so stale async work cannot leak.
    do
        local I = {
            config = {
                HOLD_MIN = 1.3, HOLD_MAX = 2.6, ENTRY_DELAY = 0.3,
                COOLDOWN = 0.05, STEAL_RANGE = 9, PRIME_RANGE = 80,
            },
            session = nil,
        }
        Grab.instant = I

        local function active(s)
            return I.session == s and valid("SEMI", s.epoch)
        end

        local function splitSyncPath(path)
            if typeof(path) == "table" then return path end
            local result = {}
            for part in string.gmatch(tostring(path), "[^%.]+") do
                table.insert(result, tonumber(part) or part)
            end
            return result
        end

        local function applyPlotSyncDiff(s, channelName, packet)
            if not active(s) or type(packet) ~= "table" then return end
            local current = s.caches[channelName]
            if type(current) ~= "table" then return end
            local parent, key
            for _, part in ipairs(splitSyncPath(packet[1])) do
                parent, key = current, part
                current = type(current) == "table" and current[part] or nil
            end
            local action, a, b = packet[2], packet[3], packet[4]
            if action == "Changed" then
                if type(parent) == "table" then parent[key] = a end
            elseif action == "ArrayInsert" then
                if type(current) == "table" then table.insert(current, b, a) end
            elseif action == "ArrayRemoved" then
                if type(current) == "table" then table.remove(current, b) end
            elseif action == "DictionaryInsert" then
                if type(current) == "table" then current[b] = a end
            elseif action == "DictionaryRemoved" then
                if type(current) == "table" then current[b] = nil end
            end
        end

        local function attachPlotChannel(s, remote)
            if not active(s) or s.channels[remote] or s.attaching[remote] then return end
            local name = tostring(remote.Name)
            if not s.plots:FindFirstChild(name) then return end
            local ticket = {}
            s.attaching[remote] = ticket
            if s.remotes.requestData and s.caches[name] == nil then
                local ok, data = pcall(function() return s.remotes.requestData:InvokeServer(name) end)
                if not active(s) or s.attaching[remote] ~= ticket or not remote.Parent then return end
                s.caches[name] = ok and type(data) == "table" and data or {}
            elseif s.caches[name] == nil then
                s.caches[name] = {}
            end
            if not active(s) or s.attaching[remote] ~= ticket or not remote.Parent then return end
            s.attaching[remote] = nil
            s.channels[remote] = remote.OnClientEvent:Connect(function(queue)
                if not active(s) or type(queue) ~= "table" then return end
                for _, packet in ipairs(queue) do applyPlotSyncDiff(s, name, packet) end
            end)
        end

        local function detachPlotChannel(s, channelName)
            for remote, connection in pairs(s.channels) do
                if tostring(remote.Name) == tostring(channelName) then
                    disconnect(connection)
                    s.channels[remote] = nil
                end
            end
            for remote in pairs(s.attaching) do
                if tostring(remote.Name) == tostring(channelName) then s.attaching[remote] = nil end
            end
            s.caches[tostring(channelName)] = nil
        end

        local function initializeSync(s)
            s.plots = workspace:FindFirstChild("Plots") or workspace:WaitForChild("Plots", 10)
            if not active(s) or not s.plots then return false end
            local packages = ReplicatedStorage:WaitForChild("Packages", 10)
            local datas = ReplicatedStorage:WaitForChild("Datas", 10)
            if not active(s) or not packages or not datas then return false end
            local animalsModule = datas:WaitForChild("Animals", 10)
            local synchronizer = packages:WaitForChild("Synchronizer", 10)
            if not active(s) or not animalsModule or not synchronizer then return false end
            s.animalsData = require(animalsModule)
            if not active(s) or type(s.animalsData) ~= "table" then return false end
            local channelFolder = synchronizer:WaitForChild("Channel", 10)
            local routeRemote = synchronizer:WaitForChild("CommunicationRoute", 10)
            if not active(s) or not channelFolder or not routeRemote then return false end
            s.remotes = {
                channelFolder = channelFolder,
                routeRemote = routeRemote,
                requestData = synchronizer:FindFirstChild("RequestData"),
            }
            table.insert(s.connections, channelFolder.ChildAdded:Connect(function(child)
                if active(s) and child:IsA("RemoteEvent") then
                    task.spawn(attachPlotChannel, s, child)
                end
            end))
            table.insert(s.connections, channelFolder.ChildRemoved:Connect(function(child)
                if active(s) then detachPlotChannel(s, tostring(child.Name)) end
            end))
            table.insert(s.connections, routeRemote.OnClientEvent:Connect(function(actions)
                if not active(s) or type(actions) ~= "table" then return end
                for _, action in ipairs(actions) do
                    if type(action) ~= "table" then continue end
                    local kind, name = action[1], tostring(action[2])
                    if kind == "ListenerRemoved" then
                        detachPlotChannel(s, name)
                    elseif kind == "ListenerAdded" and s.plots:FindFirstChild(name) then
                        local remote = channelFolder:FindFirstChild(name)
                        if remote and remote:IsA("RemoteEvent") then task.spawn(attachPlotChannel, s, remote) end
                    end
                end
            end))
            for _, child in ipairs(channelFolder:GetChildren()) do
                if not active(s) then return false end
                if child:IsA("RemoteEvent") then attachPlotChannel(s, child) end
            end
            return active(s)
        end

        local function getPlotOwner(plot)
            local sign = plot:FindFirstChild("PlotSign")
            local surface = sign and sign:FindFirstChild("SurfaceGui")
            local frame = surface and surface:FindFirstChild("Frame")
            local label = frame and frame:FindFirstChild("TextLabel")
            if not label or label.Text == "Empty Base" then return nil end
            return label.Text:gsub("'s [Bb]ase$", ""):gsub("%s+$", "")
        end

        local function getAnimalPosition(s, animal)
            local plot = s.plots and s.plots:FindFirstChild(animal.plot)
            local podiums = plot and plot:FindFirstChild("AnimalPodiums")
            local podium = podiums and podiums:FindFirstChild(animal.slot)
            if not podium then return nil end
            local ok, pivot = pcall(function() return podium:GetPivot() end)
            return ok and pivot.Position or nil
        end

        local function rootPart()
            local character = LP.Character
            return character and (character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("UpperTorso"))
        end

        local function distToAnimal(s, animal)
            local root, position = rootPart(), getAnimalPosition(s, animal)
            return root and position and (root.Position - position).Magnitude or math.huge
        end

        local function pickClosest(s)
            local root = rootPart()
            if not root then return nil end
            local best, bestDistance = nil, math.huge
            for _, animal in ipairs(s.animals) do
                local plot = s.plots:FindFirstChild(animal.plot)
                if not plot or getPlotOwner(plot) == LP.DisplayName then continue end
                local position = getAnimalPosition(s, animal)
                if not position then continue end
                local distance = (root.Position - position).Magnitude
                if distance <= I.config.PRIME_RANGE and distance < bestDistance then
                    best, bestDistance = animal, distance
                end
            end
            return best
        end

        local function findPrompt(s, animal)
            local cached = s.prompts[animal.uid]
            if cached and cached.Parent then return cached end
            local plot = s.plots:FindFirstChild(animal.plot)
            local podiums = plot and plot:FindFirstChild("AnimalPodiums")
            local podium = podiums and podiums:FindFirstChild(animal.slot)
            local base = podium and podium:FindFirstChild("Base")
            local spawn = base and base:FindFirstChild("Spawn")
            local attachment = spawn and spawn:FindFirstChild("PromptAttachment")
            if not attachment then return nil end
            for _, prompt in ipairs(attachment:GetChildren()) do
                if prompt:IsA("ProximityPrompt") then
                    s.prompts[animal.uid] = prompt
                    return prompt
                end
            end
            return nil
        end

        local function scanAllPlots(s)
            if not active(s) or not s.plots then return end
            local animals = {}
            for _, plot in ipairs(s.plots:GetChildren()) do
                local cache = s.caches[plot.Name]
                local animalList = cache and cache.AnimalList
                if type(animalList) ~= "table" then continue end
                for slot, animal in pairs(animalList) do
                    local animalName = type(animal) == "table" and animal.Index
                    local info = animalName and s.animalsData[animalName]
                    if not info then continue end
                    table.insert(animals, {
                        name = info.DisplayName or animalName,
                        plot = plot.Name, slot = tostring(slot),
                        uid = plot.Name .. "_" .. tostring(slot),
                    })
                end
            end
            s.animals = animals
        end

        local function execute(s, prompt, animal)
            if not active(s) or s.state.active or not prompt.Parent then return end
            local data = collectCallbacks(s.callbacks, prompt)
            -- The supplied instant engine requires captured prompt callbacks.
            if #data.hold == 0 and #data.trigger == 0 then
                s.callbacks[prompt] = nil -- Retry when the game's callbacks become available.
                return
            end
            if not data.ready then return end
            local character = LP.Character
            if not character then return end
            local function current()
                return active(s) and LP.Character == character and prompt.Parent ~= nil
            end
            data.ready = false
            local state = s.state
            state.active, state.startTime, state.phase = true, tick(), "holding"
            state.label = animal.name or "Animal"
            syncIsStealing()
            task.spawn(function()
                local fired = false
                local ok, err = pcall(function()
                    if not current() then return end
                    dispatch(data.hold, current)
                    task.wait(I.config.HOLD_MIN)
                    if not current() then return end
                    state.phase = "waitingRange"
                    local alreadyInRange = distToAnimal(s, animal) <= I.config.STEAL_RANGE
                    while current() do
                        if tick() - state.startTime > I.config.HOLD_MAX then break end
                        if distToAnimal(s, animal) <= I.config.STEAL_RANGE then
                            if not alreadyInRange then task.wait(I.config.ENTRY_DELAY) end
                            if not current() then return end
                            dispatch(data.trigger, current)
                            fired = true
                            break
                        end
                        task.wait()
                    end
                end)
                if not active(s) then data.ready = true; return end
                state.active = false
                if LP.Character ~= character then
                    state.phase, state.lastResultTime = "idle", 0
                else
                    state.phase = fired and "success" or "failed"
                    state.lastResultTime = tick()
                    if fired then state.totalSteals += 1 else state.failedSteals += 1 end
                end
                syncIsStealing()
                if not ok then warn("[M10RU Duels SEMI] " .. tostring(err)) end
                task.wait(I.config.COOLDOWN)
                data.ready = true
            end)
        end

        function I.stop()
            local s = I.session
            I.session = nil
            disconnect(Conns.autoStealSemi)
            Conns.autoStealSemi = nil
            if not s then return end
            s.state.active = false
            s.ready = false
            for _, connection in ipairs(s.connections) do disconnect(connection) end
            for _, connection in pairs(s.channels) do disconnect(connection) end
            table.clear(s.connections)
            table.clear(s.channels)
            table.clear(s.attaching)
            table.clear(s.caches)
            table.clear(s.prompts)
            table.clear(s.callbacks)
            table.clear(s.animals)
        end

        function I.start()
            I.stop()
            local s = {
                epoch = Grab.epoch, ready = false, scanTime = 0,
                connections = {}, channels = {}, attaching = {}, caches = {},
                prompts = {}, callbacks = {}, animals = {}, animalsData = {},
                state = {active = false, startTime = 0, phase = "idle", label = "",
                    lastResultTime = 0, totalSteals = 0, failedSteals = 0},
            }
            I.session = s
            Conns.autoStealSemi = RunService.Heartbeat:Connect(function(dt)
                if not active(s) or not s.ready then return end
                s.scanTime += dt or 0.016
                if s.scanTime >= 5 then
                    s.scanTime = 0
                    scanAllPlots(s)
                end
                if s.state.active then return end
                local target = pickClosest(s)
                local prompt = target and findPrompt(s, target)
                if prompt then execute(s, prompt, target) end
            end)
            task.spawn(function()
                local ok, result = pcall(initializeSync, s)
                if not active(s) then return end
                if not ok or not result then
                    s.error = ok and "Required Plots / Animals / Synchronizer data is unavailable." or tostring(result)
                    warn("[M10RU Duels SEMI] " .. s.error)
                    return
                end
                scanAllPlots(s)
                s.ready = true
            end)
        end
    end

    function Grab.stopAll()
        -- Invalidate BEFORE changing flags/disconnecting: old sleeping tasks cannot fire.
        Grab.epoch += 1
        State.SemiNormalOpen, State.SemiEnabled = false, false
        State.StealV1.AutoStealEnabled, State.StealV2.AutoStealEnabled = false, false
        disconnect(Conns.autoStealV1); Conns.autoStealV1 = nil
        disconnect(Conns.autoStealV2); Conns.autoStealV2 = nil
        Grab.instant.stop()
        State.StealV1.Data, State.StealV2.Data = {}, {}
        State.isStealingV1, State.isStealingV2 = false, false
        State.stealStartTimeV2 = nil
        Grab.progressV1, Grab.v2Ready = 0, false
        Grab.phaseV1, Grab.phaseV2 = "idle", "idle"
        syncIsStealing()
    end

    function Grab.startNormal()
        if not Grab.alive then return end
        Grab.stopAll()
        State.SemiNormalOpen = true
        Grab.uiTarget = State.SemiMode
        if State.SemiMode == "V1" then
            State.StealV1.AutoStealEnabled = true
            Conns.autoStealV1 = RunService.Heartbeat:Connect(function()
                if not State.StealV1.AutoStealEnabled or State.isStealingV1 then return end
                local prompt, name = findNearestPromptV1()
                if prompt then executeStealV1(prompt, name) end
            end)
        else
            State.StealV2.AutoStealEnabled = true
            Conns.autoStealV2 = RunService.Heartbeat:Connect(function()
                if not State.StealV2.AutoStealEnabled or State.isStealingV2 then return end
                local prompt = findNearestPromptV2()
                Grab.v2Ready = prompt ~= nil
                if prompt then executeStealV2(prompt) end
            end)
        end
        Grab.refresh()
    end

    function Grab.startSemi()
        if not Grab.alive then return end
        Grab.stopAll()
        State.SemiEnabled = true
        Grab.uiTarget = "SEMI"
        Grab.instant.start()
        Grab.refresh()
    end

    function Grab.toggleNormal()
        if not Grab.alive then return end
        if State.SemiNormalOpen then Grab.stopAll(); Grab.refresh() else Grab.startNormal() end
    end

    function Grab.toggleSemi()
        if not Grab.alive then return end
        if State.SemiEnabled then Grab.stopAll(); Grab.refresh() else Grab.startSemi() end
    end

    function Grab.switchMode(mode)
        if not Grab.alive or (mode ~= "V1" and mode ~= "V2") then return end
        if State.SemiMode == mode then Grab.refresh(); return end
        local restart = State.SemiNormalOpen
        State.SemiMode, Grab.uiTarget = mode, mode
        if restart then Grab.startNormal() else Grab.refresh() end
    end

    function Grab.getProgress()
        local engine = Grab.currentEngine()
        if engine == "V1" then return math.clamp(Grab.progressV1, 0, 1) end
        if engine == "V2" then
            if State.isStealingV2 and State.stealStartTimeV2 then
                return math.clamp((tick() - State.stealStartTimeV2) / math.max(State.StealV2.HalfHoldMin, 0.01), 0, 1)
            end
            return Grab.v2Ready and 1 or 0
        end
        if engine == "SEMI" then
            local s = Grab.instant.session
            if not s or not s.ready then return 0 end
            if s.state.active then
                return math.clamp((tick() - s.state.startTime) / Grab.instant.config.HOLD_MAX, 0, 1)
            end
            if s.state.lastResultTime > 0 and tick() - s.state.lastResultTime < 1.4 then return 1 end
            return (math.sin(tick() * 2.2) * 0.5 + 0.5) * 0.75
        end
        return 0
    end

    function Grab.isReady()
        local engine = Grab.currentEngine()
        if engine == "V1" then
            return State.isStealingV1 and (Grab.phaseV1 == "waitingRange" or Grab.phaseV1 == "finishing")
        elseif engine == "V2" then
            return State.isStealingV2 and Grab.phaseV2 == "waitingRange"
        elseif engine == "SEMI" then
            local session = Grab.instant.session
            return session ~= nil and session.state.active and session.state.phase == "waitingRange"
        end
        return false
    end

    function Grab.loadSettings(cfg)
        if cfg.semiMode == "V1" or cfg.semiMode == "V2" then State.SemiMode = cfg.semiMode end
        Grab.uiTarget = State.SemiMode
        for _, key in ipairs({"v1Scale", "v2Scale", "semiScale"}) do
            local value = cfg[key]
            if type(value) == "number" and value == value and math.abs(value) < math.huge then
                State[key] = math.clamp(value, 0.5, 2)
            end
        end
        if type(cfg.autoGrabStyle) == "table" then
            for _, engine in ipairs({"V1", "V2", "SEMI"}) do
                local style = cfg.autoGrabStyle[engine]
                if style == 1 or style == 2 then State.AutoGrabStyle[engine] = style end
            end
        end
        if cfg.autoGrabSchema == 2 then
            -- If a damaged config enables both, SEMI wins; never start two engines.
            Grab.restoreRequested = cfg.semiEnabled == true and "SEMI"
                or cfg.semiNormalOpen == true and "NORMAL" or nil
        else
            -- Old semiEnabled was the NORMAL master; do not reinterpret it as instant.
            Grab.restoreRequested = cfg.semiEnabled == true and "NORMAL" or nil
        end
    end

    function Grab.restore()
        if Grab.restoreRequested == "SEMI" then
            Grab.startSemi()
        elseif Grab.restoreRequested == "NORMAL" then
            Grab.startNormal()
        else
            Grab.refresh()
        end
    end

    function Grab.destroy()
        if not Grab.alive then return end
        Grab.stopAll()
        Grab.alive = false
        disconnect(Grab.renderConnection)
        Grab.renderConnection = nil
        for _, connection in ipairs(Grab.connections) do disconnect(connection) end
        table.clear(Grab.connections)
    end
end

UI.addCleanup(Grab.destroy)

-- ========================================================================
-- AUTO LEFT & AUTO RIGHT PATHRUNNERS
-- ========================================================================
local alPhase, arPhase = 1, 1

local function stopAutoLeft()
    if Conns.autoLeft then Conns.autoLeft:Disconnect(); Conns.autoLeft = nil end
    alPhase = 1
    local char, hum = getCharData()
    if hum then hum:Move(Vector3.zero, false) end
    if autoLeftSetVisual then autoLeftSetVisual(false) end
end

local function stopAutoRight()
    if Conns.autoRight then Conns.autoRight:Disconnect(); Conns.autoRight = nil end
    arPhase = 1
    local char, hum = getCharData()
    if hum then hum:Move(Vector3.zero, false) end
    if autoRightSetVisual then autoRightSetVisual(false) end
end

local function startAutoLeft()
    if Conns.autoLeft then Conns.autoLeft:Disconnect() end
    alPhase = 1
    Conns.autoLeft = RunService.Heartbeat:Connect(function()
        if not State.autoLeftEnabled or State.ragdollTpBusy then return end
        local char, hum, hrp = getCharData()
        if not hrp or not hum then return end
        if isRagdollState(hum) then hum:Move(Vector3.zero, false); return end
        
        local spd = getAutoPathSpeed()
        if alPhase == 1 then
            local tgt = Vector3.new(State.AP_L1.X, hrp.Position.Y, State.AP_L1.Z)
            if (tgt - hrp.Position).Magnitude < 1.2 then
                alPhase = 2
                local d = State.AP_L2 - hrp.Position
                local mv = Vector3.new(d.X, 0, d.Z).Unit
                hum:Move(mv, false)
                applyPathMovement(hum, hrp, mv, spd)
                return
            end
            local d = State.AP_L1 - hrp.Position
            local mv = Vector3.new(d.X, 0, d.Z).Unit
            hum:Move(mv, false)
            applyPathMovement(hum, hrp, mv, spd)
        elseif alPhase == 2 then
            local tgt = Vector3.new(State.AP_L2.X, hrp.Position.Y, State.AP_L2.Z)
            if (tgt - hrp.Position).Magnitude < 1.2 then
                hum:Move(Vector3.zero, false)
                hrp.AssemblyLinearVelocity = Vector3.zero
                State.autoLeftEnabled = false
                stopAutoLeft()
                return
            end
            local d = State.AP_L2 - hrp.Position
            local mv = Vector3.new(d.X, 0, d.Z).Unit
            hum:Move(mv, false)
            applyPathMovement(hum, hrp, mv, spd)
        end
    end)
end

local function startAutoRight()
    if Conns.autoRight then Conns.autoRight:Disconnect() end
    arPhase = 1
    Conns.autoRight = RunService.Heartbeat:Connect(function()
        if not State.autoRightEnabled or State.ragdollTpBusy then return end
        local char, hum, hrp = getCharData()
        if not hrp or not hum then return end
        if isRagdollState(hum) then hum:Move(Vector3.zero, false); return end
        
        local spd = getAutoPathSpeed()
        if arPhase == 1 then
            local tgt = Vector3.new(State.AP_R1.X, hrp.Position.Y, State.AP_R1.Z)
            if (tgt - hrp.Position).Magnitude < 1.2 then
                arPhase = 2
                local d = State.AP_R2 - hrp.Position
                local mv = Vector3.new(d.X, 0, d.Z).Unit
                hum:Move(mv, false)
                applyPathMovement(hum, hrp, mv, spd)
                return
            end
            local d = State.AP_R1 - hrp.Position
            local mv = Vector3.new(d.X, 0, d.Z).Unit
            hum:Move(mv, false)
            applyPathMovement(hum, hrp, mv, spd)
        elseif arPhase == 2 then
            local tgt = Vector3.new(State.AP_R2.X, hrp.Position.Y, State.AP_R2.Z)
            if (tgt - hrp.Position).Magnitude < 1.2 then
                hum:Move(Vector3.zero, false)
                hrp.AssemblyLinearVelocity = Vector3.zero
                State.autoRightEnabled = false
                stopAutoRight()
                return
            end
            local d = State.AP_R2 - hrp.Position
            local mv = Vector3.new(d.X, 0, d.Z).Unit
            hum:Move(mv, false)
            applyPathMovement(hum, hrp, mv, spd)
        end
    end)
end

local function queueAutoLeftStart()
    State.autoLeftEnabled = true
    if State.autoRightEnabled then State.autoRightEnabled = false; stopAutoRight() end
    if State.autoBatEnabled then Combat.stopGood() end
    startAutoLeft()
end

local function queueAutoRightStart()
    State.autoRightEnabled = true
    if State.autoLeftEnabled then State.autoLeftEnabled = false; stopAutoLeft() end
    if State.autoBatEnabled then Combat.stopGood() end
    startAutoRight()
end

-- ========================================================================
-- RAGDOLL TP: Ragdoll Teleport.txt sequence, independent of path-running buttons.
-- Choose one side (or deselect it). Each hit runs A -> B -> final, 0.12s apart.
-- Cancellation guards stop old checkpoints after Off, side changes or respawn.
-- ========================================================================
local RagdollTP = {alive = true, generation = 0, hasRecovered = true, connections = {},
    checkpointA = Vector3.new(-472.60, -7.00, 57.52),
    checkpointLeft = Vector3.new(-472.65, -7.00, 95.69),
    checkpointRight = Vector3.new(-471.76, -7.00, 26.22),
    finalLeft = Vector3.new(-483.59, -5.04, 104.24),
    finalRight = Vector3.new(-483.51, -5.10, 18.89)}
do
    local function disconnect(connection) if connection then connection:Disconnect() end end
    local function isRagdoll(state)
        return state == Enum.HumanoidStateType.Physics or state == Enum.HumanoidStateType.Ragdoll
            or state == Enum.HumanoidStateType.FallingDown
    end
    function RagdollTP.refresh()
        if RagdollTP.refreshUI then RagdollTP.refreshUI() end
    end
    function RagdollTP.cancel()
        RagdollTP.generation += 1
        State.ragdollTpBusy = false
    end
    function RagdollTP.runSequence(side, character, humanoid, root)
        if State.ragdollTpBusy or not State.ragdollTpEnabled then return end
        local generation = RagdollTP.generation
        local function current()
            return RagdollTP.alive and State.ragdollTpEnabled and State.ragdollTpSide == side
                and RagdollTP.generation == generation and LP.Character == character and character.Parent
                and humanoid.Parent and humanoid.Health > 0 and root.Parent
                and character:FindFirstChild("HumanoidRootPart") == root
        end
        if not current() then return end
        State.ragdollTpBusy = true
        RagdollTP.hasRecovered = false
        local intermediate = side == "Left" and RagdollTP.checkpointLeft or RagdollTP.checkpointRight
        local final = side == "Left" and RagdollTP.finalLeft or RagdollTP.finalRight
        task.spawn(function()
            local ok, err = pcall(function()
                local function move(position)
                    if not current() then return false end
                    character:PivotTo(CFrame.new(position))
                    root.AssemblyLinearVelocity = Vector3.zero
                    return true
                end
                if not move(RagdollTP.checkpointA) then return end
                task.wait(0.12)
                if not move(intermediate) then return end
                task.wait(0.12)
                move(final)
            end)
            if RagdollTP.generation == generation then
                State.ragdollTpBusy = false
                if not ok then warn("[M10RU Duels Ragdoll tp] " .. tostring(err)) end
            end
        end)
    end
    function RagdollTP.observeState(state, character, humanoid)
        if not RagdollTP.alive or not State.ragdollTpEnabled or character ~= LP.Character
            or not character or not character.Parent or not humanoid or humanoid.Health <= 0 then return end
        if RagdollTP.character ~= character or RagdollTP.humanoid ~= humanoid then RagdollTP.bindCharacter() end
        if not isRagdoll(state) then RagdollTP.hasRecovered = true; return end
        if State.ragdollTpBusy or not RagdollTP.hasRecovered then return end
        local side = State.ragdollTpSide
        local root = character:FindFirstChild("HumanoidRootPart")
        if root and (side == "Left" or side == "Right") then RagdollTP.runSequence(side, character, humanoid, root) end
    end
    function RagdollTP.bindCharacter()
        local character, humanoid = getCharData()
        if RagdollTP.character ~= character or RagdollTP.humanoid ~= humanoid then
            RagdollTP.cancel()
            disconnect(RagdollTP.stateConnection); RagdollTP.stateConnection = nil
            RagdollTP.character, RagdollTP.humanoid = character, humanoid
            RagdollTP.hasRecovered = true
            if character and humanoid then
                -- A state event also catches hits recovered before the next Heartbeat.
                RagdollTP.stateConnection = humanoid.StateChanged:Connect(function(_, state)
                    if RagdollTP.character == character and RagdollTP.humanoid == humanoid then
                        RagdollTP.observeState(state, character, humanoid)
                    end
                end)
            end
        end
        return character, humanoid
    end
    function RagdollTP.step()
        if not RagdollTP.alive or not State.ragdollTpEnabled then return end
        local character, humanoid = RagdollTP.bindCharacter()
        if character and humanoid then RagdollTP.observeState(humanoid:GetState(), character, humanoid) end
    end
    function RagdollTP.setEnabled(on)
        if not RagdollTP.alive then return end
        on = on == true
        if State.ragdollTpEnabled == on and (not on or RagdollTP.heartbeat) then RagdollTP.refresh(); return end
        RagdollTP.cancel()
        disconnect(RagdollTP.heartbeat); RagdollTP.heartbeat = nil
        disconnect(RagdollTP.stateConnection); RagdollTP.stateConnection = nil
        RagdollTP.character, RagdollTP.humanoid = nil, nil
        RagdollTP.hasRecovered = true
        State.ragdollTpEnabled = on
        if on then
            RagdollTP.bindCharacter()
            RagdollTP.heartbeat = RunService.Heartbeat:Connect(RagdollTP.step)
        end
        RagdollTP.refresh()
    end
    function RagdollTP.selectSide(side)
        if not RagdollTP.alive or not State.ragdollTpEnabled or (side ~= "Left" and side ~= "Right") then return end
        RagdollTP.cancel()
        State.ragdollTpSide = State.ragdollTpSide == side and "None" or side
        RagdollTP.refresh()
    end
    function RagdollTP.loadSettings(cfg)
        local side = cfg.ragdollTpSide
        State.ragdollTpSide = (side == "Left" or side == "Right") and side or "None"
        RagdollTP.restoreWanted = cfg.ragdollTpEnabled == true
    end
    function RagdollTP.restore() RagdollTP.setEnabled(RagdollTP.restoreWanted == true) end
    local function resetForCharacter()
        RagdollTP.cancel()
        disconnect(RagdollTP.stateConnection); RagdollTP.stateConnection = nil
        RagdollTP.character, RagdollTP.humanoid = nil, nil
        RagdollTP.hasRecovered = true
        -- The donor clears left/right on respawn. Keep the parent menu open.
        State.ragdollTpSide = "None"
        RagdollTP.refresh()
    end
    function RagdollTP.destroy()
        if not RagdollTP.alive then return end
        RagdollTP.setEnabled(false)
        RagdollTP.alive = false
        for _, connection in ipairs(RagdollTP.connections) do disconnect(connection) end
        table.clear(RagdollTP.connections)
    end
    table.insert(RagdollTP.connections, LP.CharacterRemoving:Connect(resetForCharacter))
    table.insert(RagdollTP.connections, LP.CharacterAdded:Connect(resetForCharacter))
    UI.addCleanup(RagdollTP.destroy)
end

-- ========================================================================
-- ANTI RAGDOLL: OFF / ORIGINAL NORMAL (V1) / Unpatched Old Anti rag (V2).
-- V1 stays on RenderStepped. V2 uses the donor Heartbeat + 0.15s reset gate.
-- The old V2 constraint-destruction/attribute/yaw reset is not used by V2.
-- ========================================================================
local Ragdoll = {alive = true, open = false, cameraRecord = nil,
    generation = 0, lastReset = 0, resetBusy = false}
do
    local function releaseCamera()
        local record = Ragdoll.cameraRecord
        Ragdoll.cameraRecord = nil
        if record then
            pcall(function()
                if record.camera.CameraSubject == record.humanoid then record.camera.CameraSubject = record.previous end
            end)
        end
    end
    local function bindCamera(humanoid)
        local camera = workspace.CurrentCamera
        if not camera then return end
        local record = Ragdoll.cameraRecord
        if not record or record.camera ~= camera or record.humanoid ~= humanoid then
            releaseCamera()
            Ragdoll.cameraRecord = {camera = camera, humanoid = humanoid, previous = camera.CameraSubject}
        end
        camera.CameraSubject = humanoid
    end
    local function removeConstraintsV1(character)
        for _, item in ipairs(character:GetDescendants()) do
            if item:IsA("BallSocketConstraint") or (item:IsA("Attachment") and item.Name:find("RagdollAttachment")) then
                pcall(function() item:Destroy() end)
            end
        end
    end
    local function isDonorRagdoll(state)
        return state == Enum.HumanoidStateType.Physics or state == Enum.HumanoidStateType.Ragdoll
            or state == Enum.HumanoidStateType.FallingDown
    end
    function Ragdoll.resetV2(character, humanoid, root)
        local generation = Ragdoll.generation
        local function current()
            return Ragdoll.alive and State.antiRagdollMode == "Custom" and Ragdoll.generation == generation
                and LP.Character == character and character.Parent and humanoid.Parent and root.Parent and humanoid.Health > 0
        end
        if not current() or Ragdoll.resetBusy then return end
        Ragdoll.resetBusy = true
        local ok, err = pcall(function()
            humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
            -- Deprecated and current velocity properties are both in the donor.
            pcall(function() root.Velocity = Vector3.zero; root.RotVelocity = Vector3.zero end)
            root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
            for _, object in ipairs(character:GetDescendants()) do
                if object:IsA("Motor6D") or object:IsA("Constraint") then
                    pcall(function() object.Enabled = true end)
                end
            end
            bindCamera(humanoid)
            local playerScripts = LP:FindFirstChild("PlayerScripts")
            local playerModule = playerScripts and playerScripts:FindFirstChild("PlayerModule")
            local controlModule = playerModule and playerModule:FindFirstChild("ControlModule")
            if controlModule then
                local loaded, controls = pcall(require, controlModule)
                if not current() then return end
                if loaded and controls and type(controls.Enable) == "function" then
                    pcall(function() controls:Enable() end)
                end
            end
            if not current() then return end
            humanoid.AutoRotate = true
            humanoid.PlatformStand = false
            humanoid.Sit = false
        end)
        if Ragdoll.generation == generation then
            Ragdoll.resetBusy = false
            if not ok then warn("[M10RU Duels Anti Ragdoll V2] " .. tostring(err)) end
        end
    end
    function Ragdoll.step()
        if not Ragdoll.alive or State.antiRagdollMode == "Off" then return end
        local character, humanoid, root = getCharData()
        if not character or not humanoid or not root or not humanoid.Parent or humanoid.Health <= 0 then return end
        local state = humanoid:GetState()
        if State.antiRagdollMode == "Custom" then
            if isDonorRagdoll(state) then
                -- Notify before recovery changes the state; Ragdoll TP must not miss a hit.
                RagdollTP.observeState(state, character, humanoid)
                local now = tick()
                if not Ragdoll.resetBusy and now - Ragdoll.lastReset > 0.15 then
                    Ragdoll.lastReset = now
                    Ragdoll.resetV2(character, humanoid, root)
                end
            end
            return
        end
        -- Original V1 behavior, preserved separately.
        local ragdolled = isRagdollState(humanoid)
        local endTime = LP:GetAttribute("RagdollEndTime")
        if not ragdolled and type(endTime) == "number" then ragdolled = endTime > workspace:GetServerTimeNow() end
        if not ragdolled then return end
        if isDonorRagdoll(state) then RagdollTP.observeState(state, character, humanoid) end
        removeConstraintsV1(character)
        pcall(function() LP:SetAttribute("RagdollEndTime", workspace:GetServerTimeNow()) end)
        humanoid.PlatformStand = false
        pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.GettingUp) end)
        pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.Running) end)
        root.Anchored = false
        root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
        root.CFrame = CFrame.new(root.Position) * CFrame.Angles(0, select(2, root.CFrame:ToEulerAnglesYXZ()), 0)
        bindCamera(humanoid)
    end
    function Ragdoll.refresh()
        if Ragdoll.refreshUI then Ragdoll.refreshUI() end
    end
    function Ragdoll.setMode(mode)
        if not Ragdoll.alive or (mode ~= "Off" and mode ~= "Normal" and mode ~= "Custom") then return end
        if State.antiRagdollMode == mode and (mode == "Off" or Conns.antiRag) then Ragdoll.refresh(); return end
        Ragdoll.generation += 1
        if Conns.antiRag then Conns.antiRag:Disconnect(); Conns.antiRag = nil end
        releaseCamera()
        Ragdoll.resetBusy, Ragdoll.lastReset = false, 0
        State.antiRagdollMode, State.antiRagdollEnabled = mode, mode ~= "Off"
        if mode == "Normal" then Conns.antiRag = RunService.RenderStepped:Connect(Ragdoll.step)
        elseif mode == "Custom" then Conns.antiRag = RunService.Heartbeat:Connect(Ragdoll.step) end
        Ragdoll.refresh()
    end
    function Ragdoll.destroy()
        if not Ragdoll.alive then return end
        Ragdoll.setMode("Off")
        Ragdoll.alive = false
    end
    UI.addCleanup(Ragdoll.destroy)
end
local function startAntiRagdoll()
    Ragdoll.setMode(State.antiRagdollMode ~= "Off" and State.antiRagdollMode or "Normal")
end
local function stopAntiRagdoll() Ragdoll.setMode("Off") end

-- ========================================================================
-- INFINITE JUMP
-- ========================================================================
UserInputService.JumpRequest:Connect(function()
    if not State.infJumpEnabled then return end
    local char, hum, root = getCharData()
    if root then
        root.Velocity = Vector3.new(root.Velocity.X, 55, root.Velocity.Z)
    end
end)

RunService.Heartbeat:Connect(function()
    if not State.infJumpEnabled then return end
    local char, hum, root = getCharData()
    if not root or not hum then return end
    
    if State.infJumpMode == "hold" then
        local jumpHeld = UserInputService:IsKeyDown(Enum.KeyCode.Space) or hum.Jump == true
        if jumpHeld and root.Velocity.Y < 30 then
            root.Velocity = Vector3.new(root.Velocity.X, 55, root.Velocity.Z)
        end
    elseif State.infJumpMode == "manual" then
        if UserInputService:IsKeyDown(Enum.KeyCode.Space) and root.Velocity.Y < 30 then
            root.Velocity = Vector3.new(root.Velocity.X, 55, root.Velocity.Z)
        end
    end
    if root.Velocity.Y < -120 then
        root.Velocity = Vector3.new(root.Velocity.X, -120, root.Velocity.Z)
    end
end)

-- ========================================================================
-- UNWALK & DROP & TP FLOOR
-- ========================================================================
local unwalkSavedAnimate = nil
local function startUnwalk()
    local char, hum = getCharData()
    if hum then
        for _, t in ipairs(hum:GetPlayingAnimationTracks()) do
            pcall(function() t:Stop() end)
        end
    end
    if char then
        local anim = char:FindFirstChild("Animate")
        if anim then
            unwalkSavedAnimate = anim:Clone()
            anim:Destroy()
        end
    end
end

local function stopUnwalk()
    local char = LP.Character
    if char and unwalkSavedAnimate then
        unwalkSavedAnimate:Clone().Parent = char
        unwalkSavedAnimate = nil
    end
end

local function runDrop()
    if State.dropActive then return end
    if State.autoBatEnabled then Combat.stopGood() end
    local char, hum, root = getCharData()
    if not root then return end
    
    State.dropActive = true
    local startTime = tick()
    local conn
    conn = RunService.Heartbeat:Connect(function()
        local c, h, r = getCharData()
        if not r then
            conn:Disconnect()
            State.dropActive = false
            return
        end
        if tick() - startTime >= State.DROP_ASCEND_DURATION then
            conn:Disconnect()
            local rp = RaycastParams.new()
            rp.FilterDescendantsInstances = {c}
            rp.FilterType = Enum.RaycastFilterType.Exclude
            local rayResult = workspace:Raycast(r.Position, Vector3.new(0, -2000, 0), rp)
            if rayResult then
                local hum2 = c:FindFirstChildOfClass("Humanoid")
                local offset = (hum2 and hum2.HipHeight or 2) + (r.Size.Y / 2)
                r.CFrame = CFrame.new(r.Position.X, rayResult.Position.Y + offset, r.Position.Z)
                r.AssemblyLinearVelocity = Vector3.zero
            end
            State.dropActive = false
            return
        end
        r.AssemblyLinearVelocity = Vector3.new(r.AssemblyLinearVelocity.X, State.DROP_ASCEND_SPEED, r.AssemblyLinearVelocity.Z)
    end)
end

local function doAutoTPDown(force)
    if State.ragdollTpBusy then return end
    local char, hum, hrp = getCharData()
    if not hrp or not hum then return end
    if not force then
        if hum.FloorMaterial ~= Enum.Material.Air then return end
        if hrp.Position.Y < State.autoTPHeight then return end
    end
    hrp.CFrame = CFrame.new(hrp.Position.X, -7.00, hrp.Position.Z) * CFrame.Angles(0, select(2, hrp.CFrame:ToEulerAnglesYXZ()), 0)
    hrp.AssemblyLinearVelocity = Vector3.zero
end

local function startAutoTP()
    if Conns.autoTP then task.cancel(Conns.autoTP); Conns.autoTP = nil end
    Conns.autoTP = task.spawn(function()
        while State.autoTPEnabled do
            task.wait(0.1)
            pcall(function() doAutoTPDown(false) end)
        end
    end)
end

local function stopAutoTP()
    State.autoTPEnabled = false
    if Conns.autoTP then task.cancel(Conns.autoTP); Conns.autoTP = nil end
end

local function runTPFloor()
    pcall(function() doAutoTPDown(true) end)
end

-- ========================================================================
-- CLEAN ANTI DIE: local health/death-state logic only.
-- No donor GUI, overhead text, hotkeys, images, config or external loader.
-- Local client protection is not a guarantee against server-authoritative death.
-- ========================================================================
AntiDie = {alive = true, generation = 0, connections = {},
    deathLocks = setmetatable({}, {__mode = "k"}), healing = false}
do
    local function disconnect(connection) if connection then connection:Disconnect() end end
    -- Both the existing aimbot and this toggle use the Dead state. Neither may
    -- restore it while the other still owns it; restore the original once last.
    function AntiDie.acquireDead(humanoid, owner)
        local record = AntiDie.deathLocks[humanoid]
        if not record then
            local original = true
            pcall(function() original = humanoid:GetStateEnabled(Enum.HumanoidStateType.Dead) end)
            record = {original = original, owners = {}}
            AntiDie.deathLocks[humanoid] = record
        end
        record.owners[owner] = true
        pcall(function() humanoid:SetStateEnabled(Enum.HumanoidStateType.Dead, false) end)
    end
    function AntiDie.releaseDead(humanoid, owner)
        local record = AntiDie.deathLocks[humanoid]
        if not record then return end
        record.owners[owner] = nil
        if next(record.owners) then
            pcall(function() humanoid:SetStateEnabled(Enum.HumanoidStateType.Dead, false) end)
        else
            AntiDie.deathLocks[humanoid] = nil
            pcall(function() humanoid:SetStateEnabled(Enum.HumanoidStateType.Dead, record.original) end)
        end
    end
    local function unprotect()
        local record = AntiDie.owner
        AntiDie.owner = nil
        AntiDie.healing = false
        if not record then return end
        for _, connection in ipairs(record.connections) do disconnect(connection) end
        -- Default Roblox health restores to 100 like the donor, but custom
        -- games retain their original MaxHealth rather than being forced to 100.
        pcall(function()
            record.humanoid.MaxHealth = record.maxHealth
            record.humanoid.Health = record.maxHealth
        end)
        AntiDie.releaseDead(record.humanoid, "toggle")
    end
    local function refill(record)
        if not AntiDie.alive or not State.antiDieEnabled or AntiDie.owner ~= record
            or not record.humanoid.Parent or AntiDie.healing then return end
        AntiDie.healing = true
        pcall(function()
            if record.humanoid.Health < record.humanoid.MaxHealth then record.humanoid.Health = math.huge end
        end)
        AntiDie.healing = false
    end
    function AntiDie.protectCharacter(character, generation)
        if not AntiDie.alive or not State.antiDieEnabled or LP.Character ~= character or not character then return end
        local humanoid = character:FindFirstChildOfClass("Humanoid") or character:WaitForChild("Humanoid", 5)
        if not humanoid or not AntiDie.alive or not State.antiDieEnabled or generation ~= AntiDie.generation
            or LP.Character ~= character or not character.Parent then return end
        if AntiDie.owner and AntiDie.owner.humanoid == humanoid then return end
        unprotect()
        local record = {humanoid = humanoid, character = character, maxHealth = humanoid.MaxHealth, connections = {}}
        AntiDie.owner = record
        AntiDie.acquireDead(humanoid, "toggle")
        pcall(function() humanoid.MaxHealth = math.huge; humanoid.Health = math.huge end)
        table.insert(record.connections, humanoid.StateChanged:Connect(function(_, state)
            if not AntiDie.alive or not State.antiDieEnabled or AntiDie.owner ~= record then return end
            if state == Enum.HumanoidStateType.Dead then
                pcall(function() humanoid.Health = math.huge end)
                AntiDie.acquireDead(humanoid, "toggle")
            end
        end))
        table.insert(record.connections, humanoid:GetPropertyChangedSignal("Health"):Connect(function() refill(record) end))
    end
    function AntiDie.refresh()
        if AntiDie.visual then AntiDie.visual(State.antiDieEnabled) end
    end
    function AntiDie.setEnabled(on)
        if not AntiDie.alive then return end
        on = on == true
        if State.antiDieEnabled == on and (not on or AntiDie.heartbeat) then AntiDie.refresh(); return end
        AntiDie.generation += 1
        State.antiDieEnabled = on
        for _, connection in ipairs(AntiDie.connections) do disconnect(connection) end
        table.clear(AntiDie.connections)
        disconnect(AntiDie.heartbeat); AntiDie.heartbeat = nil
        unprotect()
        if on then
            local generation = AntiDie.generation
            task.spawn(AntiDie.protectCharacter, LP.Character, generation)
            table.insert(AntiDie.connections, LP.CharacterRemoving:Connect(function()
                AntiDie.generation += 1
                unprotect()
            end))
            table.insert(AntiDie.connections, LP.CharacterAdded:Connect(function(character)
                local currentGeneration = AntiDie.generation
                task.delay(0.1, function() AntiDie.protectCharacter(character, currentGeneration) end)
            end))
            AntiDie.heartbeat = RunService.Heartbeat:Connect(function()
                local record = AntiDie.owner
                if record then refill(record) end
            end)
        end
        AntiDie.refresh()
    end
    function AntiDie.destroy()
        if not AntiDie.alive then return end
        AntiDie.setEnabled(false)
        AntiDie.alive = false
    end
    UI.addCleanup(AntiDie.destroy)
end


-- ========================================================================
-- INSTANT RESET: Horizon/Nexus reset sequence.
-- This is an action, not an aimbot toggle. It temporarily releases Anti Die,
-- locks the camera, removes character collision and uses Horizon's HipHeight /
-- hard-kill fallback until Roblox creates the next character.
-- ========================================================================
InstantReset = {
    alive = true, resetCooldown = false, generation = 0,
    respawnConn = nil, connections = {},
}
do
    -- INSTA RESET: ported from the attached LaunchSystemUI script.
    -- Keep the existing M10RU controls, but use the supplied launch force
    -- and Scriptable-camera sequence instead of the previous reset engine.
    local function disconnect(connection)
        if connection then pcall(function() connection:Disconnect() end) end
    end

    function InstantReset.reset()
        if not InstantReset.alive or InstantReset.resetCooldown then return false end
        local character = LP.Character
        if not character then return false end
        local hrp = character:FindFirstChild("HumanoidRootPart")
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if not hrp or not humanoid then return false end

        InstantReset.resetCooldown = true
        InstantReset.generation += 1
        local generation = InstantReset.generation
        disconnect(InstantReset.respawnConn)
        InstantReset.respawnConn = nil

        local camera = workspace.CurrentCamera or Camera
        local savedCFrame = camera and camera.CFrame
        if camera then
            pcall(function()
                camera.CameraType = Enum.CameraType.Scriptable
                if savedCFrame then camera.CFrame = savedCFrame end
            end)
        end

        InstantReset.respawnConn = LP.CharacterAdded:Connect(function(newCharacter)
            task.wait(0.1)
            if not InstantReset.alive or generation ~= InstantReset.generation then return end
            local newHumanoid = newCharacter:FindFirstChildOfClass("Humanoid")
                or newCharacter:WaitForChild("Humanoid", 3)
            local activeCamera = workspace.CurrentCamera or camera
            if activeCamera then
                pcall(function()
                    activeCamera.CameraType = Enum.CameraType.Custom
                    if newHumanoid then activeCamera.CameraSubject = newHumanoid end
                end)
            end
            disconnect(InstantReset.respawnConn)
            InstantReset.respawnConn = nil
            InstantReset.resetCooldown = false
        end)

        -- Supplied Insta Reset launch force; no visual explosion is created.
        pcall(function()
            hrp.AssemblyLinearVelocity = Vector3.new(0, 3e6, 0)
        end)
        return true
    end

    function InstantReset.stop()
        InstantReset.generation += 1
        disconnect(InstantReset.respawnConn)
        InstantReset.respawnConn = nil
        InstantReset.resetCooldown = false
        local camera = workspace.CurrentCamera or Camera
        local character = LP.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if camera then
            pcall(function()
                camera.CameraType = Enum.CameraType.Custom
                if humanoid then camera.CameraSubject = humanoid end
            end)
        end
    end

    function InstantReset.destroy()
        if not InstantReset.alive then return end
        InstantReset.alive = false
        InstantReset.stop()
        for _, connection in ipairs(InstantReset.connections) do disconnect(connection) end
        table.clear(InstantReset.connections)
    end
    UI.addCleanup(InstantReset.destroy)
end

-- ========================================================================
-- DONOR COMBAT ENGINE: good.aimbot.txt (Insta Reset is a separate action).
-- Existing hub controls call these APIs; superseded motion loops are removed.
-- ========================================================================
do
    local G = {alive = true, enabled = false, generation = 0, connections = {}, antiDie = {},
        speed = 56.5, meleeOffset = 2, autoDropBrainrot = true, highlightEnabled = true}
    Combat.good = G

    local slapNames = {"Bat", "Slap", "Iron Slap", "Gold Slap", "Diamond Slap", "Emerald Slap", "Ruby Slap",
        "Dark Matter Slap", "Flame Slap", "Nuclear Slap", "Galaxy Slap", "Glitched Slap"}
    local function disconnect(connection) if connection then connection:Disconnect() end end
    local function findGoodBat()
        local char = LP.Character
        if not char then return nil end
        local backpack = LP:FindFirstChildOfClass("Backpack")
        for _, container in ipairs(backpack and {char, backpack} or {char}) do
            for _, tool in ipairs(container:GetChildren()) do
                if tool:IsA("Tool") and (tool.Name:lower():find("bat") or tool.Name:lower():find("slap")) then return tool end
            end
        end
        for _, name in ipairs(slapNames) do
            local tool = char:FindFirstChild(name) or (backpack and backpack:FindFirstChild(name))
            if tool then return tool end
        end
    end
    -- Shared utility for the unchanged Bat Counter feature, not an aim engine.
    function Combat.swingCounter()
        local char, hum = getCharData()
        if not char or not hum then return end
        local bat = findGoodBat()
        if not bat then return end
        if bat.Parent ~= char then pcall(function() hum:EquipTool(bat) end) end
        local remote = bat:FindFirstChildOfClass("RemoteEvent") or bat:FindFirstChildOfClass("RemoteFunction")
        if remote and remote:IsA("RemoteEvent") then pcall(function() remote:FireServer() end)
        else pcall(function() bat:Activate() end) end
    end

    -- good.aimbot: locked target, speed 56.5, prediction /150 (0.05..0.2),
    -- 2-stud behind offset, +2.6 height, -15 degree pitch, optional jump-drop.
    -- Repair the previous version's unscoped workspace highlight only.
    -- Never remove highlights belonging to the game or to other scripts.
    for _, effect in ipairs(workspace:GetChildren()) do
        if effect:IsA("Highlight") and effect.Name == "M10RUAimbotTarget" then
            effect.Enabled = false
            effect:Destroy()
        elseif effect:IsA("Folder") and effect.Name == "M10RUDuelsEffects"
            and effect:GetAttribute("M10RUDuelsOwned") == true then
            effect:Destroy()
        end
    end
    G.effects = Instance.new("Folder")
    G.effects.Name = "M10RUDuelsEffects"
    G.effects:SetAttribute("M10RUDuelsOwned", true)
    G.effects.Parent = workspace
    G.highlight = Instance.new("Highlight")
    -- Highlight defaults to its parent when Adornee is nil. Disable it BEFORE
    -- parenting and use a geometry-free holder, NEVER Workspace as its parent.
    G.highlight.Enabled = false
    G.highlight.Name = "M10RUAimbotTarget"
    G.highlight.FillColor, G.highlight.OutlineColor = UI.theme.accent, UI.theme.light
    G.highlight.FillTransparency, G.highlight.OutlineTransparency = 0.5, 0
    G.highlight.Adornee = nil
    G.highlight.Parent = G.effects
    function G.setHighlightTarget(character)
        local valid = G.alive and G.enabled and State.autoBatEnabled and G.highlightEnabled
            and typeof(character) == "Instance" and character ~= workspace and character ~= LP.Character
            and character:IsA("Model") and character.Parent ~= nil
            and character:FindFirstChildOfClass("Humanoid") and character:FindFirstChild("HumanoidRootPart")
        if not valid then character = nil end
        if G.highlightTarget ~= character then
            disconnect(G.highlightTargetGone)
            G.highlightTargetGone = nil
            G.highlightTarget = character
            if character then
                G.highlightTargetGone = character.Destroying:Connect(function()
                    if G.highlightTarget == character then G.setHighlightTarget(nil) end
                end)
            end
        end
        if character then
            if G.highlight.Adornee ~= character then
                G.highlight.Enabled = false
                G.highlight.Adornee = character
            end
            G.highlight.Enabled = true
        else
            G.highlight.Enabled = false
            G.highlight.Adornee = nil
        end
    end
    local function validGoodTarget(character)
        if not character or not character.Parent then return false end
        return character:FindFirstChildOfClass("Humanoid") and character:FindFirstChild("HumanoidRootPart")
    end
    local function getGoodTarget(root)
        if G.locked and not validGoodTarget(G.locked) then G.locked = nil end
        if G.locked then return G.locked:FindFirstChild("HumanoidRootPart"), G.locked end
        local best, distance = nil, math.huge
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LP and validGoodTarget(player.Character) then
                local other = player.Character:FindFirstChild("HumanoidRootPart")
                local d = (other.Position - root.Position).Magnitude
                if d < distance then best, distance = player.Character, d end
            end
        end
        G.locked = best
        return best and best:FindFirstChild("HumanoidRootPart"), best
    end
    local function restoreGoodOwner()
        for _, connection in ipairs(G.antiDie) do disconnect(connection) end
        table.clear(G.antiDie)
        if G.owner then
            local owner = G.owner
            pcall(function()
                owner.humanoid.BreakJointsOnDeath = owner.breakJoints
                AntiDie.releaseDead(owner.humanoid, "aimbot")
                owner.humanoid.AutoRotate = owner.autoRotate
                if G.dropping then owner.humanoid.Jump = false end
            end)
            pcall(function() owner.root.AssemblyLinearVelocity = Vector3.zero end)
        end
        G.owner, G.dropping = nil, false
    end
    local function bindGood(humanoid, root)
        if G.owner and G.owner.humanoid == humanoid then return end
        restoreGoodOwner()
        local enabled = true
        pcall(function() enabled = humanoid:GetStateEnabled(Enum.HumanoidStateType.Dead) end)
        G.owner = {humanoid = humanoid, root = root, breakJoints = humanoid.BreakJointsOnDeath,
            deadEnabled = enabled, autoRotate = humanoid.AutoRotate}
        humanoid.BreakJointsOnDeath = false
        AntiDie.acquireDead(humanoid, "aimbot")
        table.insert(G.antiDie, humanoid:GetPropertyChangedSignal("Health"):Connect(function()
            if G.alive and G.enabled and State.autoBatEnabled and G.owner and G.owner.humanoid == humanoid and humanoid.Health <= 0 then
                humanoid.Health = humanoid.MaxHealth
            end
        end))
    end
    local function holdingBrainrot(char)
        for _, tool in ipairs(char:GetChildren()) do
            if tool:IsA("Tool") then
                local name = tool.Name:lower()
                if not name:find("bat") and not name:find("slap") and not name:find("medusa") then return true end
            end
        end
        return false
    end
    function G.step()
        if not G.alive or State.ragdollTpBusy then return end
        if not G.enabled or not State.autoBatEnabled then G.setHighlightTarget(nil); return end
        local char, hum, root = getCharData()
        if not char or not char.Parent or not hum or not root then G.setHighlightTarget(nil); return end
        bindGood(hum, root)
        if hum.Health <= 0 then G.setHighlightTarget(nil); return end
        if G.dropping then return end
        local generation = G.generation
        hum.AutoRotate = false
        local bat = findGoodBat()
        if bat and bat.Parent ~= char then pcall(function() hum:EquipTool(bat) end) end
        if G.autoDropBrainrot and holdingBrainrot(char) then
            G.dropping = true
            hum.Jump = true
            task.wait(0.1)
            if not G.alive or not G.enabled or generation ~= G.generation or LP.Character ~= char then return end
            hum.Jump = false
            G.dropping = false
        end
        if not G.enabled or generation ~= G.generation or not State.autoBatEnabled or State.ragdollTpBusy then return end
        hum:Move(Vector3.zero, false)
        local target, targetCharacter = getGoodTarget(root)
        if target and targetCharacter and target.Parent and targetCharacter.Parent then
            G.noTargetSince = nil
            G.setHighlightTarget(targetCharacter)
            local velocity = target.AssemblyLinearVelocity
            local predicted = target.Position + velocity * math.clamp(velocity.Magnitude / 150, 0.05, 0.2)
            local stand = predicted - target.CFrame.LookVector * G.meleeOffset + Vector3.new(0, 2.6, 0)
            local move = stand - root.Position
            local look = Vector3.new(predicted.X, root.Position.Y, predicted.Z)
            if (look - root.Position).Magnitude > 0.1 then root.CFrame = CFrame.lookAt(root.Position, look) * CFrame.Angles(math.rad(-15), 0, 0) end
            root.AssemblyLinearVelocity = move.Magnitude > 1 and move.Unit * G.speed or velocity
        else
            G.setHighlightTarget(nil)
            G.noTargetSince = G.noTargetSince or tick()
            if tick() - G.noTargetSince > 1.5 then
                G.locked = nil
                root.AssemblyLinearVelocity = Vector3.zero
            end
        end
        -- Retain the hub's separate Auto Swing switch; this is not the old aim/movement engine.
        if State.autoSwingEnabled and bat then pcall(function() bat:Activate() end) end
    end
    function G.stopLoop()
        G.generation += 1
        disconnect(G.heartbeat); G.heartbeat = nil
        restoreGoodOwner()
        G.locked, G.noTargetSince = nil, nil
        G.setHighlightTarget(nil)
    end
    function G.startLoop()
        G.stopLoop()
        local _, hum, root = getCharData()
        if hum and root then bindGood(hum, root) end
        G.heartbeat = RunService.Heartbeat:Connect(G.step)
    end
    function G.setEnabled(on)
        on = on == true
        if not G.alive then return end
        G.enabled, State.autoBatEnabled = on, on
        if on then
            if not G.heartbeat then G.startLoop() end
        else G.stopLoop() end
    end

    function Combat.refresh()
        if setAutoBatVisual then setAutoBatVisual(State.autoBatEnabled) end
        if Combat.mobileGood then Combat.mobileGood(State.autoBatEnabled) end
    end
    function Combat.stopGood()
        G.setEnabled(false)
        if Combat.autoTPWasEnabled then
            Combat.autoTPWasEnabled = false
            State.autoTPEnabled = true
            if setAutoTPVisual then setAutoTPVisual(true) end
            startAutoTP()
        end
        Combat.refresh()
    end
    function Combat.startGood()
        if State.autoLeftEnabled then State.autoLeftEnabled = false; if Conns.autoLeft then Conns.autoLeft:Disconnect(); Conns.autoLeft = nil end end
        if State.autoRightEnabled then State.autoRightEnabled = false; if Conns.autoRight then Conns.autoRight:Disconnect(); Conns.autoRight = nil end end
        if not G.enabled and State.autoTPEnabled then Combat.autoTPWasEnabled = true; stopAutoTP() end
        G.setEnabled(true)
        Combat.refresh()
    end
    function Combat.destroy()
        G.setEnabled(false)
        G.alive = false
        for _, connection in ipairs(G.connections) do disconnect(connection) end
        table.clear(G.connections)
        G.effects:Destroy()
    end
    table.insert(G.connections, LP.CharacterRemoving:Connect(function() G.stopLoop() end))
    table.insert(G.connections, LP.CharacterAdded:Connect(function(character)
        task.delay(0.5, function()
            if LP.Character ~= character or not G.alive then return end
            if G.enabled and State.autoBatEnabled then G.startLoop() end
        end)
    end))
    UI.addCleanup(Combat.destroy)
end
local function equipAndSwingBat() Combat.swingCounter() end
local function resetAutoBatMotion() Combat.good.stopLoop() end
local function enableAutoBat() Combat.startGood() end
local function disableAutoBat() Combat.stopGood() end
local function queueAutoBatStart() Combat.startGood() end

-- ========================================================================
-- MEDUSA & BAT COUNTER
-- ========================================================================
local function findMedusa()
    local char = LP.Character
    if char then
        for _, t in ipairs(char:GetChildren()) do
            if t:IsA("Tool") and (t.Name:lower():find("medusa") or t.Name:lower():find("head") or t.Name:lower():find("stone")) then
                return t
            end
        end
    end
    local bp = LP:FindFirstChild("Backpack")
    if bp then
        for _, t in ipairs(bp:GetChildren()) do
            if t:IsA("Tool") and (t.Name:lower():find("medusa") or t.Name:lower():find("head") or t.Name:lower():find("stone")) then
                return t
            end
        end
    end
    return nil
end

local function useMedusaCounter()
    if State.medusaDebounce or tick() - State.medusaLastUsed < State.MEDUSA_COOLDOWN then return end
    local char, hum = getCharData()
    if not char or not hum then return end
    
    State.medusaDebounce = true
    local med = findMedusa()
    if not med then State.medusaDebounce = false; return end
    if med.Parent ~= char then pcall(function() hum:EquipTool(med) end) end
    pcall(function() med:Activate() end)
    State.medusaLastUsed = tick()
    State.medusaDebounce = false
end

local function onAnchorChanged(part)
    return part:GetPropertyChangedSignal("Anchored"):Connect(function()
        if part.Anchored and part.Transparency == 1 then
            useMedusaCounter()
        end
    end)
end

local function setupMedusa(char)
    for _, c in pairs(Conns.anchor) do pcall(function() c:Disconnect() end) end
    Conns.anchor = {}
    if not char then return end
    for _, part in ipairs(char:GetDescendants()) do
        if part:IsA("BasePart") then table.insert(Conns.anchor, onAnchorChanged(part)) end
    end
    table.insert(Conns.anchor, char.DescendantAdded:Connect(function(part)
        if part:IsA("BasePart") then table.insert(Conns.anchor, onAnchorChanged(part)) end
    end))
end

local function stopMedusaCounter()
    for _, c in pairs(Conns.anchor) do pcall(function() c:Disconnect() end) end
    Conns.anchor = {}
end

local function startBatCounter()
    if Conns.batCounter then return end
    Conns.batCounter = RunService.Heartbeat:Connect(function()
        if not State.batCounterEnabled or State.batCounterDebounce then return end
        local char, hum = getCharData()
        if not hum then return end
        local st = hum:GetState()
        if st == Enum.HumanoidStateType.Physics or st == Enum.HumanoidStateType.Ragdoll or st == Enum.HumanoidStateType.FallingDown then
            State.batCounterDebounce = true
            task.spawn(function()
                equipAndSwingBat()
                task.wait(0.5)
                State.batCounterDebounce = false
            end)
        end
    end)
end

local function stopBatCounter()
    if Conns.batCounter then
        Conns.batCounter:Disconnect()
        Conns.batCounter = nil
    end
    State.batCounterDebounce = false
end



-- ========================================================================
-- BILLBOARDS: SPEED INDICATOR & HIT COUNTDOWN
-- ========================================================================
local function setupSpeedIndicator(char)
    if not Speed.alive or not char then return end
    local head = char:WaitForChild("Head", 5)
    if not head or not Speed.alive or char ~= LP.Character then return end
    if Speed.billboard then pcall(function() Speed.billboard:Destroy() end) end
    for _, name in ipairs({"M10RUOverheadBB", "M10RUSpeedOnly"}) do
        local old = head:FindFirstChild(name)
        if old then old:Destroy() end
    end
    -- Invisible attachment container; its ONLY visible child is the number.
    local bb = Instance.new("BillboardGui", head)
    bb.Name = "M10RUSpeedOnly"
    bb.Size = UDim2.fromOffset(90, 26)
    bb.StudsOffset = Vector3.new(0, 2.8, 0)
    bb.AlwaysOnTop = true
    speedLabel = Instance.new("TextLabel", bb)
    speedLabel.Name = "SpeedValue"
    speedLabel.Size = UDim2.new(1, 0, 1, 0)
    speedLabel.BackgroundTransparency = 1
    speedLabel.BorderSizePixel = 0
    speedLabel.Text = "0.0"
    speedLabel.TextColor3 = UI.theme.text
    speedLabel.TextStrokeColor3 = UI.theme.background
    speedLabel.TextStrokeTransparency = 0.5
    speedLabel.Font = Enum.Font.GothamBold
    speedLabel.TextSize = 18
    speedLabel.TextXAlignment = Enum.TextXAlignment.Center
    speedLabel.TextYAlignment = Enum.TextYAlignment.Center
    Speed.billboard = bb
end
UI.addCleanup(function()
    if Speed.billboard then pcall(function() Speed.billboard:Destroy() end); Speed.billboard = nil end
    speedLabel = nil
end)

local countdownBB = nil
local countdownLabel = nil
local countdownActive = false
local countdownStateConn = nil

local function createCountdownBB(char)
    if not char then return end
    local head = char:FindFirstChild("Head")
    if not head then return end
    if countdownBB then pcall(function() countdownBB:Destroy() end) end
    
    countdownBB = Instance.new("BillboardGui", head)
    countdownBB.Name = "M10RUCountdownBB"
    countdownBB.Size = UDim2.new(0, 140, 0, 60)
    countdownBB.StudsOffset = Vector3.new(0, 5.5, 0)
    countdownBB.AlwaysOnTop = true
    countdownBB.Enabled = false
    
    countdownLabel = Instance.new("TextLabel", countdownBB)
    countdownLabel.Size = UDim2.new(1, 0, 1, 0)
    countdownLabel.BackgroundTransparency = 1
    countdownLabel.Text = ""
    countdownLabel.Font = Enum.Font.GothamBlack
    countdownLabel.TextScaled = true
    countdownLabel.TextStrokeTransparency = 0
    countdownLabel.TextStrokeColor3 = UI.theme.background
    countdownLabel.TextColor3 = UI.theme.text
end

local function runCountdown()
    if countdownActive then return end
    countdownActive = true
    if not countdownBB or not countdownLabel then
        createCountdownBB(LP.Character)
    end
    if not countdownBB or not countdownLabel then countdownActive = false; return end
    
    countdownBB.Enabled = true
    local steps = {
        {text = "3", color = UI.theme.deep},
        {text = "2", color = UI.theme.accent},
        {text = "1", color = UI.theme.light},
        {text = "GRAB!", color = UI.theme.text},
    }
    for _, step in ipairs(steps) do
        if not countdownLabel or not countdownLabel.Parent then break end
        countdownLabel.Text = step.text
        countdownLabel.TextColor3 = step.color
        task.wait(1)
    end
    if countdownBB then countdownBB.Enabled = false end
    if countdownLabel then countdownLabel.Text = "" end
    countdownActive = false
end

local function setupCountdown(char)
    if countdownStateConn then countdownStateConn:Disconnect() end
    task.wait(0.3)
    createCountdownBB(char)
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    countdownStateConn = hum.StateChanged:Connect(function(_, newState)
        if newState == Enum.HumanoidStateType.Physics
            or newState == Enum.HumanoidStateType.Ragdoll
            or newState == Enum.HumanoidStateType.FallingDown then
            task.spawn(runCountdown)
        end
    end)
end

-- Connect Character Events
LP.CharacterAdded:Connect(function(char)
    task.wait(0.5)
    setupSpeedIndicator(char)
    setupCountdown(char)
    if State.medusaCounterEnabled then setupMedusa(char) end
    if State.batCounterEnabled then startBatCounter() end
    if State.unwalkEnabled then task.wait(0.5); startUnwalk() end
    if State.antiRagdollEnabled then startAntiRagdoll() end
end)
if LP.Character then
    setupSpeedIndicator(LP.Character)
    setupCountdown(LP.Character)
end

