    Instance.new("UICorner", uiHeader).CornerRadius = UDim.new(0, 18)
    local headerPatch = Instance.new("Frame", uiHeader)
    headerPatch.Size = UDim2.new(1, 0, 0, 18)
    headerPatch.Position = UDim2.new(0, 0, 1, -18)
    headerPatch.BackgroundColor3 = UI.theme.background
    headerPatch.BorderSizePixel = 0
    headerPatch.ZIndex = 20
    local headerLine = Instance.new("Frame", uiHeader)
    headerLine.Size = UDim2.new(1, -20, 0, 1)
    headerLine.Position = UDim2.new(0, 10, 1, -1)
    headerLine.BackgroundColor3 = UI.theme.border
    headerLine.BorderSizePixel = 0
    headerLine.ZIndex = 21

    -- Header artwork restored above the section tabs. The asset itself carries
    -- the title/effects, so no duplicate text label is placed over it.
    local headerImage = Instance.new("ImageLabel", uiHeader)
    headerImage.Name = "HeaderAsset"
    headerImage.Size = UDim2.new(1, -8, 0, 84)
    headerImage.Position = UDim2.new(0, 4, 0, 1)
    headerImage.BackgroundTransparency = 1
    headerImage.BorderSizePixel = 0
    -- Fixed header image: this is independent from the BACKGROUND list.
    -- Place Screenshot___Discord.jpg in the executor asset/workspace folder.
    local embeddedHeaderPNG = ""

local function decodeBase64(data)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    data = data:gsub("[^" .. alphabet .. "=]", "")
    local bits = data:gsub(".", function(c)
        if c == "=" then return "" end
        local n = alphabet:find(c, 1, true) - 1
        local out = ""
        for i = 6, 1, -1 do
            out = out .. (((n % 2^i - n % 2^(i-1)) > 0) and "1" or "0")
        end
        return out
    end)
    return bits:gsub("%d%d%d?%d?%d?%d?%d?%d?", function(byte)
        if #byte ~= 8 then return "" end
        local n = 0
        for i = 1, 8 do
            if byte:sub(i,i) == "1" then n = n + 2^(8-i) end
        end
        return string.char(n)
    end)
end

