        Instance.new("UICorner", button).CornerRadius = UDim.new(0, 5)
        local stroke = Instance.new("UIStroke", button)
        stroke.Color = UI.theme.border
        stroke.Thickness = 1
        button.Activated:Connect(function()
            UI.animate(button, {BackgroundColor3 = UI.theme.accent, TextColor3 = UI.theme.text}, 0.08)
            if callback then callback() end
            task.delay(0.18, function()
                if button.Parent then UI.animate(button, {BackgroundColor3 = UI.theme.button, TextColor3 = UI.theme.light}, 0.12) end
            end)
        end)
        return button
    end

    local function handleAutoSwitchCarrySpeed(on)
        State.autoCarrySpeedEnabled = on == true
        State.autoCarryLastSpeed = 0
